1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	)
10	
11	// RecordInfo 描述一次保存产生的记录的元信息。
12	type RecordInfo struct {
13		// ID 是记录在存档目录内的唯一标识。
14		ID RecordID
15		// Parent 是父记录标识。只有直接建立的槽首条记录没有父记录（为空）；
16		// 分支槽首条记录以来源槽记录为父，故槽首记录的 Parent 不一定为空。
17		Parent RecordID
18		// SlotFirst 表示这是所在槽的首条记录（直接建立的根记录，或从其他
19		// 槽分出的分支首记录）；它不等价于 Parent 为空。
20		SlotFirst bool
21		// Version 是记录中世界规则的版本；History 列出它不代表该版本已被
22		// 调用方接受，用 Record 读取时仍需显式给出可接受版本集合。
23		Version string
24	}
25	
26	// slotPointer 是槽指针文件的磁盘内容，指向该槽当前最新记录。
27	//
28	// History 按该槽“保存生效的次序”记录全部属于本槽的记录标识，最新在前，
29	// 末尾是槽首条记录（直接建立的根记录或分支首记录）。它只在对应记录文件
30	// 已完整落盘后才随指针原子更新，因此绝不会包含写了一半的残留文件、写完
31	// 但尚未完成保存的孤儿记录，或 CAS 竞争失败的写入。恢复读取据此遍历，
32	// 不依赖文件修改时间，也不信任受损记录文件里读出的父标识或槽首标记。
33	//
34	// 旧版本写出的指针没有 History 字段；读取时会在内存中按校验通过的父链
35	// 回退重建，不要求用户转换数据。
36	type slotPointer struct {
37		Latest  RecordID   `json:"latest"`
38		History []RecordID `json:"history,omitempty"`
39	}
40	
41	// archiveMarker 是存档目录的标记文件。
42	type archiveMarker struct {
43		Format int `json:"format"`
44	}
45	
46	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
47	// 同一目录；所有写入通过目录内的 flock 串行化。
48	type Archive struct {
49		dir string
50	}
51	
52	const (
53		markerName  = "archive.json"
54		recordsName = "records"
55		slotsName   = "slots"
56	)
57	
58	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
59	// 存档则返回错误，以免覆盖已有数据。
60	//
61	// 创建有明确的结果：要么完整成功并返回可立即使用的句柄，要么返回
62	// 错误且不返回句柄。准备必要目录、写入存档标记或建立锁文件时出错，
63	// 都会把指明失败操作与位置的错误交给调用方，并撤回本次创建已产生的
64	// 标记、锁文件与子目录——回退只限本次新增的内容：目录里原有的文件与
65	// 子目录（包括原本就存在、可直接使用的空 records/slots 子目录）以及
66	// 调用前已存在的目标目录本身都保持原样。因此失败后排除障碍即可用
67	// 同一路径重新创建，不会被上一次失败留下的标记拒绝。
68	func Create(dir string) (_ *Archive, err error) {
69		// 本次调用新产生的内容，失败时按相反顺序撤回；调用前已存在的
70		// 任何内容都不在撤回范围内。
71		var created []string
72		defer func() {
73			if err != nil {
74				for i := len(created) - 1; i >= 0; i-- {
75					os.Remove(created[i])
76				}
77			}
78		}()
79	
80		// 目标目录在调用前已存在时保留它（包括失败回退时）；不存在才
81		// 由本次创建建立，并纳入回退范围。
82		if _, statErr := os.Stat(dir); statErr != nil {
83			if !errors.Is(statErr, os.ErrNotExist) {
84				return nil, fmt.Errorf("检查存档目录 %s: %w", dir, statErr)
85			}
86			if err := os.MkdirAll(dir, 0o755); err != nil {
87				return nil, fmt.Errorf("建立存档目录 %s: %w", dir, err)
88			}
89			created = append(created, dir)
90		}
91	
92		markerPath := filepath.Join(dir, markerName)
93		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
94		if err != nil {
95			if errors.Is(err, os.ErrExist) {
96				// 已有存档：原样保留既有标记（即使它无法解析），不覆盖，
97				// 也不借回退删除；此时本次尚未产生任何新内容。
98				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
99			}
100			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
101		}
102		created = append(created, markerPath)
103		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
104		if _, err := f.Write(markerData); err != nil {
105			f.Close()
106			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
107		}
108		if err := f.Close(); err != nil {
109			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
110		}
111	
112		for _, sub := range []string{recordsName, slotsName} {
113			subPath := filepath.Join(dir, sub)
114			if fi, statErr := os.Stat(subPath); statErr == nil {
115				if !fi.IsDir() {
116					return nil, fmt.Errorf("建立存档子目录 %s: 位置已被同名文件占用", subPath)
117				}
118				// 原本就存在的子目录直接沿用，回退时保留。
119				continue
120			} else if !errors.Is(statErr, os.ErrNotExist) {
121				return nil, fmt.Errorf("检查存档子目录 %s: %w", subPath, statErr)
122			}
123			if err := os.Mkdir(subPath, 0o755); err != nil {
124				return nil, fmt.Errorf("建立存档子目录 %s: %w", subPath, err)
125			}
126			created = append(created, subPath)
127		}
128	
129		// 预先建立锁文件并同步目录，使之后的打开更稳妥。锁位置已被占用
130		// （例如已是一个目录）时明确报错，而不是留到首次保存才失败。
131		lockPath := filepath.Join(dir, "lock")
132		_, lockStatErr := os.Stat(lockPath)
133		lockExisted := lockStatErr == nil
134		if lockStatErr != nil && !errors.Is(lockStatErr, os.ErrNotExist) {
135			return nil, fmt.Errorf("检查存档锁文件 %s: %w", lockPath, lockStatErr)
136		}
137		lf, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o600)
138		if err != nil {
139			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
140		}
141		if err := lf.Close(); err != nil {
142			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
143		}
144		if !lockExisted {
145			created = append(created, lockPath)
146		}
147	
148		if err := syncDir(dir); err != nil {
149			return nil, fmt.Errorf("同步存档目录 %s: %w", dir, err)
150		}
151		return &Archive{dir: dir}, nil
152	}
153	
154	// Open 打开一个此前由 Create 建立的存档目录。
155	func Open(dir string) (*Archive, error) {
156		path := filepath.Join(dir, markerName)
157		f, err := os.Open(path)
158		if err != nil {
159			if errors.Is(err, os.ErrNotExist) {
160				return nil, &NotFoundError{}
161			}
162			return nil, err
163		}
164		defer f.Close()
165		var m archiveMarker
166		if err := json.NewDecoder(f).Decode(&m); err != nil {
167			return nil, &CorruptError{Reason: "存档标记无法解析"}
168		}
169		if m.Format != archiveFormatVersion {
170			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
171		}
172		for _, sub := range []string{recordsName, slotsName} {
173			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
174				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
175			}
176		}
177		return &Archive{dir: dir}, nil
178	}
179	
180	// Dir 返回存档目录路径。
181	func (a *Archive) Dir() string { return a.dir }
182	
183	func (a *Archive) slotPath(slot string) string {
184		return filepath.Join(a.dir, slotsName, slot+".json")
185	}
186	
187	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
188	func validSlotName(slot string) bool {
189		if slot == "" || slot == "." || slot == ".." {
190			return false
191		}
192		if filepath.IsAbs(slot) {
193			return false
194		}
195		for _, r := range slot {
196			if r == '/' || r == '\\' || r == 0 {
197				return false
198			}
199		}
200		return filepath.Clean(slot) == slot
201	}
202	
203	// readSlotPointerLocked 在调用方已持锁的前提下读取并解析槽指针文件。
204	func (a *Archive) readSlotPointerLocked(slot string) (slotPointer, error) {
205		data, err := os.ReadFile(a.slotPath(slot))
206		if err != nil {
207			if errors.Is(err, os.ErrNotExist) {
208				return slotPointer{}, &NotFoundError{Slot: slot}
209			}
210			return slotPointer{}, err
211		}
212		var p slotPointer
213		if err := json.Unmarshal(data, &p); err != nil {
214			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
215		}
216		if p.Latest == "" {
217			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
218		}
219		return p, nil
220	}
221	
222	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
223	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
224		p, err := a.readSlotPointerLocked(slot)
225		if err != nil {
226			return "", err
227		}
228		return p.Latest, nil
229	}
230	
231	// Save 在存档中保存一个世界。
232	//
233	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
234	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。
235	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
236		if !validSlotName(slot) {
237			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
238		}
239		st := w.Snapshot()
240	
241		lock, err := acquireLock(a.dir)
242		if err != nil {
243			return RecordInfo{}, err
244		}
245		defer lock.release()
246	
247		// 持锁后再次确认槽不存在。
248		if _, err := a.readLatestLocked(slot); err == nil {
249			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
250		} else if !errors.As(err, new(*NotFoundError)) {
251			return RecordInfo{}, err
252		}
253	
254		id, err := newRecordID()
255		if err != nil {
256			return RecordInfo{}, err
257		}
258		env := &envelope{
259			Format:    recordFormatVersion,
260			ID:        id,
261			SlotFirst: true,
262			State:     st,
263		}
264		env.Checksum = computeChecksum(env)
265		if err := writeRecord(a.dir, env); err != nil {
266			return RecordInfo{}, err
267		}
268		if err := a.createSlotPointer(slot, id); err != nil {
269			return RecordInfo{}, err
270		}
271		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
272	}
273	
274	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
275	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
276	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。新槽的
277	// 历史索引只含其首条记录本身——分支槽不会把来源槽的记录计入候选。
278	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
279		slotsDir := filepath.Join(a.dir, slotsName)
280		final := a.slotPath(slot)
281		data, _ := json.MarshalIndent(slotPointer{
282			Latest:  id,
283			History: []RecordID{id},
284		}, "", "  ")
285	
286		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
287		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
288		if err != nil {
289			return err
290		}
291		if _, err := f.Write(data); err != nil {
292			f.Close()
293			os.Remove(tmp)
294			return err
295		}
296		if err := f.Sync(); err != nil {
297			f.Close()
298			os.Remove(tmp)
299			return err
300		}
301		if err := f.Close(); err != nil {
302			os.Remove(tmp)
303			return err
304		}
305		if err := os.Link(tmp, final); err != nil {
306			os.Remove(tmp)
307			if errors.Is(err, os.ErrExist) {
308				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
309			}
310			return err
311		}
312		os.Remove(tmp)
313		return syncDir(slotsDir)
314	}
315	
316	// Replace 用世界当前状态覆盖槽的最新记录。
317	//
318	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
319	// 写入才会发生；否则返回 *ConflictError——即使该标识对应的旧文件恰好
320	// 已损坏或被删除，过期请求也只报冲突，不改报文件错误。标识匹配时还要
321	// 确认这条当前记录本身可正常读取：文件缺失返回 *NotFoundError；格式版本
322	// 不受支持、截断、校验和不匹配、世界状态不合法或父记录缺失返回
323	// *CorruptError。绝不用
324	// 调用方传入的完整世界掩盖当前记录的问题，也不自动改选较老记录为父。
325	// 新记录的父记录就是被覆盖的那次记录。同一目录下并发覆盖同一父记录时
326	// 只有一个成功。被拒绝的覆盖不改变槽指向、历史与任何已有记录。
327	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
328		if !validSlotName(slot) {
329			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
330		}
331		if expected == "" {
332			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
333		}
334		st := w.Snapshot()
335	
336		lock, err := acquireLock(a.dir)
337		if err != nil {
338			return RecordInfo{}, err
339		}
340		defer lock.release()
341	
342		pointer, err := a.readSlotPointerLocked(slot)
343		if err != nil {
344			return RecordInfo{}, err
345		}
346		if pointer.Latest != expected {
347			return RecordInfo{}, &ConflictError{
348				Slot:   slot,
349				Reason: "所依据的记录已不是该槽最新记录",
350			}
351		}
352	
353		// 标识匹配后，当前记录本身必须可正常读取：格式受支持、完整、内容
354		// 校验通过、世界状态合法且父记录关系成立。否则以它为父保存的新记录随后也
355		// 无法读取，等于用调用方传入的完整世界掩盖了当前记录的问题；
356		// 这里沿用与读取路径一致的校验，损坏或缺失时拒绝覆盖，槽指向、
357		// 历史与已有记录保持原样，调用方可改走恢复预览与确认恢复。
358		if _, err := a.loadAndVerifyLocked(expected); err != nil {
359			if ce, ok := err.(*CorruptError); ok {
360				ce.Slot = slot
361			}
362			return RecordInfo{}, err
363		}
364	
365		// 覆盖保存传入世界的快照，以被覆盖的当前记录为父，沿用共同的
366		// 新记录组装、落盘与槽指针提交路径。
367		return a.appendSlotRecordLocked(slotSave{
368			slot:          slot,
369			oldPointer:    pointer,
370			parent:        expected,
371			historyAnchor: expected,
372			state:         st,
373		})
374	}
375	
376	// commitSlotPointerLocked 在记录文件已完整落盘后，原子更新槽指针：指向
377	// 新记录，并把历史索引按保存次序前置新记录。历史索引只在此刻（记录已
378	// 完整生效）才更新，因此残留临时文件与写完但未完成保存的孤儿记录绝不会
379	// 进入恢复候选。
380	func (a *Archive) commitSlotPointerLocked(slot string, oldPointer slotPointer, oldLatest, newID RecordID) error {
381		history, err := a.nextSlotHistoryLocked(oldPointer, oldLatest, newID)
382		if err != nil {
383			return err
384		}
385		return a.persistSlotPointerLocked(slot, slotPointer{Latest: newID, History: history})
386	}
387	
388	// replaceSlotPointer 直接把槽指针指向 id，不附带历史索引。它仅用于测试
389	// 中模拟旧版本或外部写入器留下的指针；生产写入路径一律走
390	// commitSlotPointerLocked 以维护历史索引。
391	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
392		return a.persistSlotPointerLocked(slot, slotPointer{Latest: id})
393	}
394	
395	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
396	//
397	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
398	// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
399	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
400		if !validSlotName(srcSlot) {
401			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
402		}
403		if !validSlotName(dstSlot) {
404			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
405		}
406		if src == "" {
407			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
408		}
409	
410		lock, err := acquireLock(a.dir)
411		if err != nil {
412			return RecordInfo{}, err
413		}
414		defer lock.release()
415	
416		srcEnv, err := a.loadAndVerifyLocked(src)
417		if err != nil {
418			return RecordInfo{}, err
419		}
420		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
421		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
422			return RecordInfo{}, err
423		}
424		// 目标槽重名拒绝创建。
425		if _, err := a.readLatestLocked(dstSlot); err == nil {
426			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
427		} else if !errors.As(err, new(*NotFoundError)) {
428			return RecordInfo{}, err
429		}
430	
431		id, err := newRecordID()
432		if err != nil {
433			return RecordInfo{}, err
434		}
435		env := &envelope{
436			Format:    recordFormatVersion,
437			ID:        id,
438			Parent:    src,
439			SlotFirst: true,
440			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
441			State: cloneState(srcEnv.State),
442		}
443		env.Checksum = computeChecksum(env)
444		if err := writeRecord(a.dir, env); err != nil {
445			return RecordInfo{}, err
446		}
447		if err := a.createSlotPointer(dstSlot, id); err != nil {
448			return RecordInfo{}, err
449		}
450		return RecordInfo{
451			ID:        id,
452			Parent:    src,
453			SlotFirst: true,
454			Version:   env.State.Rules.Version,
455		}, nil
456	}
457	
458	// assertInSlotHistoryLocked 确认 id 位于 slot 自身的历史次序中（分支槽
459	// 的历史只含它自己保存成功的记录，不含来源槽记录）。
460	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
461		history, err := a.slotHistoryLocked(slot)
462		if err != nil {
463			return err
464		}
465		for _, cid := range history {
466			if cid == id {
467				return nil
468			}
469		}
470		return &NotFoundError{Slot: slot, Record: id}
471	}
472	
473	// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
474	// 槽首记录在末尾）。
475	//
476	// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
477	// “校验通过”的记录父链回退重建，绝不在读取路径上改写目录。重建在缺失、
478	// 无法解析或校验不过的记录处停止——无法确认归属的更老记录不再使用。
479	// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
480	// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
481	func (a *Archive) slotHistoryLocked(slot string) ([]RecordID, error) {
482		p, err := a.readSlotPointerLocked(slot)
483		if err != nil {
484			return nil, err
485		}
486		if len(p.History) > 0 {
487			// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
488			return dedupeRecordIDs(append([]RecordID{p.Latest}, p.History...)), nil
489		}
490		return a.rebuildHistoryLocked(p.Latest)
491	}
492	
493	// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史，
494	// 只返回仍能确认属于本槽的记录；在缺失、无法解析或校验不过的记录处停止。
495	func (a *Archive) rebuildHistoryLocked(latest RecordID) ([]RecordID, error) {
496		var chain []RecordID
497		seen := map[RecordID]bool{}
498		cur := latest
499		for cur != "" {
500			if seen[cur] {
501				return nil, &CorruptError{Record: cur, Reason: "历史链出现环"}
502			}
503			seen[cur] = true
504			env, err := a.loadAndVerifyLocked(cur)
505			if err != nil {
506				// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
507				// 旧历史在此断裂；已确认的部分仍可使用。
508				return chain, nil
509			}
510			chain = append(chain, cur)
511			if env.SlotFirst {
512				return chain, nil
513			}
514			cur = env.Parent
515		}
516		return chain, nil
517	}
518	
519	// dedupeRecordIDs 按首次出现次序去重记录标识。
520	func dedupeRecordIDs(ids []RecordID) []RecordID {
521		seen := map[RecordID]bool{}
522		out := ids[:0]
523		for _, id := range ids {
524			if id == "" || seen[id] {
525				continue
526			}
527			seen[id] = true
528			out = append(out, id)
529		}
530		return out
531	}
532	
533	// persistSlotPointerLocked 以原子改名写出槽指针。
534	func (a *Archive) persistSlotPointerLocked(slot string, p slotPointer) error {
535		data, _ := json.MarshalIndent(p, "", "  ")
536		return writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data)
537	}
538	
539	// nextSlotHistory 在一次以 oldLatest 为被覆盖/升级记录的成功写入后，
540	// 生成新指针应持有的历史次序：新记录在最前，其余沿用此前已确认属于
541	// 本槽的记录。旧指针无索引时在内存中回退重建（不完整也照样承接），
542	// 从而让旧历史在第一次成功覆盖或升级后获得完整恢复能力。
543	func (a *Archive) nextSlotHistoryLocked(oldPointer slotPointer, oldLatest, newID RecordID) ([]RecordID, error) {
544		base := oldPointer.History
545		if len(base) == 0 {
546			rebuilt, err := a.rebuildHistoryLocked(oldLatest)
547			if err != nil {
548				return nil, err
549			}
550			base = rebuilt
551		}
552		return dedupeRecordIDs(append([]RecordID{newID}, base...)), nil
553	}
554	
555	// Slots 返回所有存档槽名。
556	func (a *Archive) Slots() ([]string, error) {
557		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
558		if err != nil {
559			return nil, err
560		}
561		var names []string
562		for _, e := range entries {
563			if e.IsDir() {
564				continue
565			}
566			name := e.Name()
567			if len(name) > 5 && name[len(name)-5:] == ".json" {
568				names = append(names, name[:len(name)-5])
569			}
570		}
571		return names, nil
572	}
