1	package world
2	
3	import (
4		"fmt"
5		"unicode/utf8"
6	)
7	
8	// RuleError 表示数据或提交违反了世界规则。
9	type RuleError struct {
10		Reason string
11	}
12	
13	func (e *RuleError) Error() string { return "world: " + e.Reason }
14	
15	func ruleErrorf(format string, args ...any) error {
16		return &RuleError{Reason: fmt.Sprintf(format, args...)}
17	}
18	
19	// validateRules 校验规则本身：非空版本、地点不重复且非空标识、
20	// 连通关系只引用已有地点、物品不重复、携带上限非负。
21	//
22	// 全部文本标识（版本、地点、道路端点、物品种类、携带上限的角色键）还
23	// 必须是合法 UTF-8：含无效字节的字符串经 JSON 保存会被悄悄改写成替换
24	// 字符，可能使不同标识重名，因此必须在接纳世界数据时拒绝，即使该地点、
25	// 物品或上限键暂时无人使用。
26	func validateRules(r Rules) error {
27		if !utf8.ValidString(r.Version) {
28			return ruleErrorf("规则版本不是合法 UTF-8: %q", r.Version)
29		}
30		if r.Version == "" {
31			return ruleErrorf("规则版本不能为空")
32		}
33		locs := make(map[string]struct{}, len(r.Locations))
34		for i, l := range r.Locations {
35			if !utf8.ValidString(l) {
36				return ruleErrorf("第 %d 个地点标识不是合法 UTF-8: %q", i, l)
37			}
38			if l == "" {
39				return ruleErrorf("地点标识不能为空")
40			}
41			if _, ok := locs[l]; ok {
42				return ruleErrorf("地点标识重复: %q", l)
43			}
44			locs[l] = struct{}{}
45		}
46		for i, e := range r.Edges {
47			if !utf8.ValidString(e.From) {
48				return ruleErrorf("连通关系 %d 的起点不是合法 UTF-8: %q", i, e.From)
49			}
50			if !utf8.ValidString(e.To) {
51				return ruleErrorf("连通关系 %d 的终点不是合法 UTF-8: %q", i, e.To)
52			}
53			if _, ok := locs[e.From]; !ok {
54				return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.From)
55			}
56			if _, ok := locs[e.To]; !ok {
57				return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.To)
58			}
59		}
60		kinds := make(map[string]struct{}, len(r.ItemKinds))
61		for i, k := range r.ItemKinds {
62			if !utf8.ValidString(k) {
63				return ruleErrorf("第 %d 个物品种类标识不是合法 UTF-8: %q", i, k)
64			}
65			if k == "" {
66				return ruleErrorf("物品种类标识不能为空")
67			}
68			if _, ok := kinds[k]; ok {
69				return ruleErrorf("物品种类重复: %q", k)
70			}
71			kinds[k] = struct{}{}
72		}
73		for who, limit := range r.CarryLimits {
74			if !utf8.ValidString(who) {
75				return ruleErrorf("携带上限的角色键不是合法 UTF-8: %q", who)
76			}
77			if limit < 0 {
78				return ruleErrorf("角色 %q 的携带上限不能为负: %d", who, limit)
79			}
80		}
81		return nil
82	}
83	
84	func (r Rules) adjacent(from, to string) bool {
85		for _, e := range r.Edges {
86			if (e.From == from && e.To == to) || (e.From == to && e.To == from) {
87				return true
88			}
89		}
90		return false
91	}
92	
93	// validateCharacters 校验角色集合：标识不重复、位于已有地点；
94	// 物品种类合法、数量非负、不重复，总量不超过携带上限。
95	//
96	// 角色标识、所在地点与所持物品名称同样必须是合法 UTF-8，理由与
97	// validateRules 相同：否则保存后标识可能被改写或与其他标识重名。
98	func validateCharacters(chars []Character, r Rules) error {
99		locSet := make(map[string]struct{}, len(r.Locations))
100		for _, l := range r.Locations {
101			locSet[l] = struct{}{}
102		}
103		kindSet := make(map[string]struct{}, len(r.ItemKinds))
104		for _, k := range r.ItemKinds {
105			kindSet[k] = struct{}{}
106		}
107		ids := make(map[string]struct{}, len(chars))
108		for i, c := range chars {
109			if !utf8.ValidString(c.ID) {
110				return ruleErrorf("第 %d 个角色标识不是合法 UTF-8: %q", i, c.ID)
111			}
112			if c.ID == "" {
113				return ruleErrorf("角色标识不能为空")
114			}
115			if _, ok := ids[c.ID]; ok {
116				return ruleErrorf("角色标识重复: %q", c.ID)
117			}
118			ids[c.ID] = struct{}{}
119			if !utf8.ValidString(c.Location) {
120				return ruleErrorf("角色 %q 的所在地点不是合法 UTF-8: %q", c.ID, c.Location)
121			}
122			if _, ok := locSet[c.Location]; !ok {
123				return ruleErrorf("角色 %q 位于不存在的地点: %q", c.ID, c.Location)
124			}
125			seen := make(map[string]struct{}, len(c.Items))
126			for _, it := range c.Items {
127				if !utf8.ValidString(it.Item) {
128					return ruleErrorf("角色 %q 持有名称不是合法 UTF-8 的物品: %q", c.ID, it.Item)
129				}
130				if _, ok := kindSet[it.Item]; !ok {
131					return ruleErrorf("角色 %q 持有规则不允许的物品: %q", c.ID, it.Item)
132				}
133				if _, dup := seen[it.Item]; dup {
134					return ruleErrorf("角色 %q 的物品 %q 重复列出", c.ID, it.Item)
135				}
136				seen[it.Item] = struct{}{}
137				if it.Count < 0 {
138					return ruleErrorf("角色 %q 的物品 %q 数量不能为负: %d", c.ID, it.Item, it.Count)
139				}
140			}
141			// 携带上限按真实总量判断，规则与建立世界、提交物品变化共用同一口径：
142			// 精确求和不因回绕放过超限；未设上限的角色不检查总量，其总量允许
143			// 超过 int 最大值。
144			if err := carryLimitError(c.ID, c.Items, r.CarryLimits); err != nil {
145				return err
146			}
147		}
148		return nil
149	}
150	
151	// validateInitialData 校验建立世界的初始数据。
152	func validateInitialData(d InitialData) error {
153		if err := validateRules(d.Rules); err != nil {
154			return err
155		}
156		if err := validateCharacters(d.Characters, d.Rules); err != nil {
157			return err
158		}
159		return nil
160	}
