1	package world
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"syscall"
8	)
9	
10	// Record 是一次成功保存留下的、可供读取的记录。
11	type Record struct {
12		// ID 是记录标识。
13		ID RecordID
14		// Parent 是父记录标识。只有直接建立的槽首记录没有父记录（为空）；
15		// 分支槽的首条记录以来源槽记录为父，因此“槽首记录”并不等于
16		// “没有父记录”。
17		Parent RecordID
18		// SlotFirst 表示这是其所在槽的首条记录（直接建立的根记录，或从
19		// 其他槽分出的分支首记录）；它不代表 Parent 一定为空。
20		SlotFirst bool
21		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
22		State State
23	}
24	
25	func acquireSharedLock(dir string) (*fileLock, error) {
26		path := dir + "/lock"
27		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
28		if err != nil {
29			return nil, err
30		}
31		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
32			f.Close()
33			return nil, err
34		}
35		return &fileLock{f: f}, nil
36	}
37	
38	// loadAndVerifyLocked 读取记录文件，校验其记录格式版本、内容校验和（校验和
39	// 已包含父记录关系）、父记录是否存在，以及世界数据是否自洽。
40	//
41	// 记录格式只支持 recordFormatVersion：格式编号缺失、为零、为负或为其他
42	// 正整数的记录按损坏处理，即使校验和匹配、世界状态合法、规则版本可被
43	// 调用方接受也不交付——目录能打开不代表每条记录都是当前功能理解的格式。
44	// 格式校验先于内容校验和：校验和载荷的布局本身由格式定义，未知格式的
45	// 记录无法解释其校验语义。格式问题与规则版本分别判断，格式错误一律报
46	// CorruptError，绝不报成 VersionRejectedError。
47	//
48	// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
49	// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
50	// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
51	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
52		env, err := loadRecord(recordPath(a.dir, id))
53		if err != nil {
54			if errors.Is(err, os.ErrNotExist) {
55				return nil, &NotFoundError{Record: id}
56			}
57			return nil, &CorruptError{Record: id, Reason: err.Error()}
58		}
59		if env.ID != id {
60			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
61		}
62		if env.Format != recordFormatVersion {
63			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("不支持的记录格式版本: %d", env.Format)}
64		}
65		if got := computeChecksum(env); got != env.Checksum {
66			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
67		}
68		// 父记录关系必须落到一个真实存在的记录上。
69		if env.Parent != "" {
70			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
71				if errors.Is(err, os.ErrNotExist) {
72					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
73				}
74				return nil, err
75			}
76		}
77		// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
78		// 其余状态合法，也按损坏处理，不自动把时间改成零。
79		if env.State.Time < 0 {
80			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
81		}
82		if err := validateInitialData(InitialData{
83			Seed:       env.State.Seed,
84			Rules:      env.State.Rules,
85			Characters: env.State.Characters,
86		}); err != nil {
87			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
88		}
89		return env, nil
90	}
91	
92	func versionAccepted(version string, accepted []string) bool {
93		for _, v := range accepted {
94			if v == version {
95				return true
96			}
97		}
98		return false
99	}
100	
101	func envToRecord(env *envelope) Record {
102		return Record{
103			ID:        env.ID,
104			Parent:    env.Parent,
105			SlotFirst: env.SlotFirst,
106			State:     cloneState(env.State),
107		}
108	}
109	
110	// Latest 读取槽当前最新记录。
111	//
112	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
113	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（格式版本不受支持、
114	// 校验和不符、父记录缺失、无法解析、时间片为负）时返回 *CorruptError。
115	// 格式与版本分别判断：格式不受支持的记录一律报损坏，不报版本拒绝。
116	// 读取不会改写存档。
117	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
118		if !validSlotName(slot) {
119			return Record{}, &NotFoundError{Slot: slot}
120		}
121		lock, err := acquireSharedLock(a.dir)
122		if err != nil {
123			return Record{}, err
124		}
125		defer lock.release()
126	
127		id, err := a.readLatestLocked(slot)
128		if err != nil {
129			return Record{}, err
130		}
131		env, err := a.loadAndVerifyLocked(id)
132		if err != nil {
133			if ce, ok := err.(*CorruptError); ok {
134				ce.Slot = slot
135			}
136			return Record{}, err
137		}
138		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
139			return Record{}, &VersionRejectedError{
140				Slot:     slot,
141				Record:   id,
142				Version:  env.State.Rules.Version,
143				Accepted: append([]string(nil), acceptedVersions...),
144			}
145		}
146		return envToRecord(env), nil
147	}
148	
149	// Record 按标识读取槽的一份历史记录（覆盖、升级或确认恢复之后，较早的
150	// 旧记录仍可按其标识读取）。
151	//
152	// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
153	// 且记录必须属于该槽的历史链。acceptedVersions 必须显式给出调用方可以
154	// 接受的规则版本：记录完好但版本不在集合内时返回 *VersionRejectedError。
155	// 读取不会切换槽当前记录，不会修补记录，也不会替换记录中的规则版本。
156	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
157		if !validSlotName(slot) {
158			return Record{}, &NotFoundError{Slot: slot}
159		}
160		lock, err := acquireSharedLock(a.dir)
161		if err != nil {
162			return Record{}, err
163		}
164		defer lock.release()
165	
166		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
167			return Record{}, err
168		}
169		env, err := a.loadAndVerifyLocked(id)
170		if err != nil {
171			if ce, ok := err.(*CorruptError); ok {
172				ce.Slot = slot
173			}
174			return Record{}, err
175		}
176		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
177			return Record{}, &VersionRejectedError{
178				Slot:     slot,
179				Record:   id,
180				Version:  env.State.Rules.Version,
181				Accepted: append([]string(nil), acceptedVersions...),
182			}
183		}
184		return envToRecord(env), nil
185	}
186	
187	// History 浏览槽已经保存生效的历史，返回每条记录的元信息（记录标识、
188	// 父标识、槽首标记、规则版本），供先浏览、再用 [Archive.Record] 按标识
189	// 读取完整世界。
190	//
191	// 次序按该槽“保存生效的先后”排列：最近一次成功保存的记录在最前，槽首
192	// 记录在末尾。它既不按记录里的世界时间片排序，也不按记录文件的修改时间
193	// 排序——确认恢复允许时间片回到较早来源的时刻，那次保存产生的新记录仍排
194	// 在最前，而原先已经生效的其他保存按原次序保留。
195	//
196	// 父标识表示“这条记录由哪一次保存承接而来”，与列表次序是两回事。槽首
197	// 标记不能统一解释成“父标识为空”：只有直接建立的槽首记录没有父记录；
198	// 分支槽的首条记录虽然标记为槽首，却以来源槽的那条记录为父记录。分支槽
199	// 只列分支自身保存生效的记录，不会因为分支首记录的父指向来源槽，就把
200	// 来源槽的历史补进列表。
201	//
202	// 列表只做完整性检查，不筛选规则版本：History 没有可接受版本参数，一份
203	// 记录只要确实保存生效且通过与 Record 一致的完整性检查——标识与文件一致、
204	// 记录格式受支持、内容校验和正确（含父记录关系）、世界状态合法、直接父
205	// 记录文件存在——即使规则版本较旧或陌生也照常列出。因此“出现在列表里”
206	// 只说明记录完好，不保证调用方立即可用：用 Record 读取时仍必须显式给出
207	// 可接受版本集合，版本不被接受会得到 *VersionRejectedError，不能据此认为
208	// 历史列错了。
209	//
210	// 带历史索引的槽中，单条损坏、缺失或无法解析的记录只被略过，列表继续
211	// 返回其余合格记录，最新或某条中间记录出问题不会让整个浏览失败；但直接
212	// 父记录文件被删除的子记录因不满足父关系要求也被略过，而父文件仍在、
213	// 只是内容损坏时，不因此略过自身完好的子记录。旧版本写出的无历史索引槽
214	// 沿校验通过的父链在内存中重建，只列仍能确认归属本槽的记录，重建在损坏
215	// 处停止，不能承诺越过损坏处继续寻找更老的记录。
216	//
217	// 槽存在但没有任何合格记录时，返回成功的非 nil 空列表；槽不存在返回
218	// *NotFoundError，槽指针无法解析返回 *CorruptError，三者互不等同，不能把
219	// 不存在或损坏当成空列表。浏览只做只读遍历，不切换槽当前记录、不修补或
220	// 删除记录、不改写历史与世界规则。
221	func (a *Archive) History(slot string) ([]RecordInfo, error) {
222		if !validSlotName(slot) {
223			return nil, &NotFoundError{Slot: slot}
224		}
225		lock, err := acquireSharedLock(a.dir)
226		if err != nil {
227			return nil, err
228		}
229		defer lock.release()
230	
231		history, err := a.slotHistoryLocked(slot)
232		if err != nil {
233			return nil, err
234		}
235		infos := make([]RecordInfo, 0, len(history))
236		for _, id := range history {
237			// 与 Record 相同的完整性检查（不做规则版本取舍）：任何一条
238			// 记录损坏、缺失或无法解析都只略过它本身，不读其中的父标识或
239			// 槽首标记去扩大或缩小遍历范围，也不让整个列表失败。
240			env, verifyErr := a.loadAndVerifyLocked(id)
241			if verifyErr != nil {
242				continue
243			}
244			infos = append(infos, RecordInfo{
245				ID:        env.ID,
246				Parent:    env.Parent,
247				SlotFirst: env.SlotFirst,
248				Version:   env.State.Rules.Version,
249			})
250		}
251		return infos, nil
252	}
253	
254	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
255	// 版本可接受的已保存记录。
256	//
257	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
258	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
259	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
260	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
261	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
262	// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
263	// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
264	//
265	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
266	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
267	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
268	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
269	// 不会被选中。
270	//
271	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
272	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
273	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
274	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
275	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
276		if !validSlotName(slot) {
277			return Record{}, &NotFoundError{Slot: slot}
278		}
279		lock, err := acquireSharedLock(a.dir)
280		if err != nil {
281			return Record{}, err
282		}
283		defer lock.release()
284	
285		history, err := a.slotHistoryLocked(slot)
286		if err != nil {
287			return Record{}, err
288		}
289	
290		env, err := a.firstRecoverableLocked(history, acceptedVersions)
291		if err != nil {
292			var ue *UnrecoverableError
293			if errors.As(err, &ue) {
294				ue.Slot = slot
295			}
296			return Record{}, err
297		}
298		return envToRecord(env), nil
299	}
300	
301	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
302	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
303	//
304	// 文件缺失、截断、格式版本不受支持、校验和不符、记录标识不符、父关系异常、
305	// 时间片为负或世界状态不自洽的记录一律越过（不读其中的父标识或槽首标记）；
306	// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
307	// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
308	// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
309	// 补全）。
310	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
311		var lastReason string
312		for _, id := range history {
313			env, verifyErr := a.loadAndVerifyLocked(id)
314			if verifyErr != nil {
315				lastReason = verifyErr.Error()
316				continue
317			}
318			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
319				lastReason = (&VersionRejectedError{
320					Record:  id,
321					Version: env.State.Rules.Version,
322				}).Error()
323				continue
324			}
325			return env, nil
326		}
327	
328		if lastReason == "" {
329			lastReason = "槽中没有任何可确认归属的历史记录"
330		}
331		return nil, &UnrecoverableError{Reason: lastReason}
332	}
