356		// 目标规则各类字段都要在接纳前检查（这里测一个无人使用的地点）。
357		target2 := v2Rules()
358		target2.Locations = append(target2.Locations, invalidB)
359		if _, err := a.CheckUpgrade("s", []string{"v1"}, target2); err == nil {
360			t.Fatal("含非法地点的目标规则应被拒绝")
361		} else {
362			assertInvalidRuleError(t, err, "地点")
363		}
364		if _, err := a.Upgrade("s", []string{"v1"}, target2, info.ID); err == nil {
365			t.Fatal("含非法地点的目标规则升级应被拒绝")
366		} else {
367			assertInvalidRuleError(t, err, "地点")
368		}
369	
370		// 槽当前记录与历史保持原样。
371		after, err := a.Latest("s", []string{"v1"})
372		if err != nil {
373			t.Fatalf("拒绝后槽当前记录应仍可读: %v", err)
374		}
375		if after.ID != info.ID || !reflect.DeepEqual(after.State, before.State) {
376			t.Fatalf("拒绝操作改动了槽当前记录:\n got %+v\nwant %+v", after, before)
377		}
378		hist, err := a.History("s")
379		if err != nil {
380			t.Fatal(err)
381		}
382		if len(hist) != 1 || hist[0].ID != info.ID {
383			t.Fatalf("拒绝操作改动了历史: %+v", hist)
384		}
385		// 调用方传入的规则没有被改写。
386		if target.Version != invalidA {
387			t.Fatalf("目标版本入参被改写: %q", target.Version)
388		}
389		for _, l := range target2.Locations {
390			if l == invalidB {
391				return
392			}
393		}
394		t.Fatal("目标地点入参被改写")
395	}
396	
397	// TestMigrationInvalidUTF8TargetRejected 显式迁移的预览与正式提交沿用
398	// 相同的规则合法性条件：目标规则含非法文本时两者都返回 *RuleError，槽
399	// 保持原样；转换对应关系中的非法名称同样被拒绝。
400	func TestMigrationInvalidUTF8TargetRejected(t *testing.T) {
401		a, _ := newTestArchive(t)
402		info := saveBase(t, a, "s")
403		before, err := a.Latest("s", []string{"v1"})
404		if err != nil {
405			t.Fatal(err)
406		}
407	
408		target := v2Rules()
409		target.Version = invalidA
410	
411		t.Run("预览拒绝", func(t *testing.T) {
412			preview, err := a.PreviewMigration("s", []string{"v1"}, target, nil, nil)
413			if preview.RecordID != "" {
414				t.Fatalf("非法目标规则不应返回预览: %+v", preview)
415			}
416			assertInvalidRuleError(t, err, "规则版本")
417		})
418		t.Run("正式提交拒绝", func(t *testing.T) {
419			res, err := a.Migrate("s", []string{"v1"}, target, nil, nil, info.ID)
420			if res.Record.ID != "" {
421				t.Fatalf("非法目标规则不应产生新记录: %+v", res)
422			}
423			assertInvalidRuleError(t, err, "规则版本")
424		})
425	
426		// 目标规则合法，但转换对应关系含非法 UTF-8 名称：预览与提交都拒绝。
427		goodTarget := v2Rules()
428		badMappings := []NameMapping{{From: "hall", To: invalidA}}
429		if _, err := a.PreviewMigration("s", []string{"v1"}, goodTarget, badMappings, nil); err == nil {
430			t.Fatal("含非法目标名称的转换关系应被拒绝")
431		} else {
432			assertInvalidRuleError(t, err, "转换关系")
433		}
434		if _, err := a.Migrate("s", []string{"v1"}, goodTarget, badMappings, nil, info.ID); err == nil {
435			t.Fatal("含非法目标名称的迁移提交应被拒绝")
436		} else {
437			assertInvalidRuleError(t, err, "转换关系")
438		}
439	
440		// 槽当前记录与历史保持原样，入参未被改写。
441		after, err := a.Latest("s", []string{"v1"})
442		if err != nil {
443			t.Fatalf("拒绝后槽当前记录应仍可读: %v", err)
444		}
445		if after.ID != info.ID || !reflect.DeepEqual(after.State, before.State) {
446			t.Fatalf("拒绝操作改动了槽当前记录:\n got %+v\nwant %+v", after, before)
447		}
448		if hist, err := a.History("s"); err != nil || len(hist) != 1 || hist[0].ID != info.ID {
449			t.Fatalf("拒绝操作改动了历史: %v %+v", err, hist)
450		}
451		if target.Version != invalidA || badMappings[0].To != invalidA {
452			t.Fatal("调用方入参被改写")
453		}
454	}
