93				assertUnsupportedFormatCorrupt(t, err, ids[0], format)
94	
95				_, err = a.Record("s", ids[0], []string{"v1"})
96				assertUnsupportedFormatCorrupt(t, err, ids[0], format)
97	
98				// 记录没有被悄悄修补或删除，槽指向不变。
99				if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
100					t.Fatal("读取改写了未知格式记录")
