114	// TestMissingFormatFieldRejected 记录文件缺少 format 字段时按零值处理，
115	// 即使校验和（按零值重算）匹配、世界状态合法也拒绝读取。
116	func TestMissingFormatFieldRejected(t *testing.T) {
