126	// 的完好记录仍按版本集合决定能否读取；格式不受支持的记录即使版本不被
127	// 接受也报损坏而非版本拒绝，且读取不改写记录中的规则。
128	func TestFormatCheckIndependentOfVersion(t *testing.T) {
129		a, _ := newTestArchive(t)
