142		// 记录中的规则保持原样，未被读取改写。
143		env, err := loadRecord(recordPath(a.dir, ids[0]))
144		if err != nil {
145			t.Fatal(err)
146		}
147		if env.State.Rules.Version != "v1" || env.Format != 2 {
148			t.Fatalf("读取不应改写记录: format=%d version=%s", env.Format, env.State.Rules.Version)
149		}
150	}
151	
152	// TestRecoverSkipsUnsupportedFormat 恢复读取与恢复预览按本槽保存次序越过
153	// 格式不受支持的记录；连续多份未知格式记录也不会遮住其后格式 1 的完好
154	// 记录。预览的当前标识仍是槽实际指向的记录，来源是选中的完好记录；恢复
155	// 不修补格式、不删除文件、不改变槽指向。
156	func TestRecoverSkipsUnsupportedFormat(t *testing.T) {
157		a, _ := newTestArchive(t)
