		},
	}
}

func saveFFFDWorld(t *testing.T, a *Archive, slot string) RecordInfo {
	t.Helper()
	w, err := WorldFromState(fffdState())
	if err != nil {
		t.Fatalf("含合法“�”的状态应被接受: %v", err)
	}
	info, err := a.Save(slot, w)
